CREATE OR REPLACE FUNCTION public.sanji_claim_discovery_notification(p_owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cfg public.sanji_discovery_config;u public.sanji_discovery_usage;d date:=(now() at time zone 'Asia/Seoul')::date;recipient text;s jsonb;n integer;
begin
 select * into cfg from public.sanji_discovery_config where owner=p_owner and enabled and notify_completion;
 if not found or not exists(select 1 from public.sanji_members where user_id=p_owner) then return null;end if;
 select * into u from public.sanji_discovery_usage where owner=p_owner and day=d;
 if not found or u.companies<cfg.target then return null;end if;
 select email into recipient from auth.users where id=p_owner;
 if recipient is null or recipient!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then return null;end if;
 s:=jsonb_build_object('day',d,'recipient',recipient,'target',cfg.target,'companies',u.companies,'emails',u.emails,'processed',u.processed);
 insert into public.sanji_discovery_notifications(owner,day,snapshot) values(p_owner,d,s) on conflict do nothing;
 get diagnostics n=row_count;
 if n=0 then return null;end if;
 return s;
end $function$

CREATE OR REPLACE FUNCTION public.sanji_claim_search_sources(p_owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.sanji_discovery_config;s jsonb;d text:=(now() at time zone 'Asia/Seoul')::date::text;c integer;
begin
 select * into r from public.sanji_discovery_config where owner=p_owner and enabled for update;
 if not found then return null;end if;
 if exists(select 1 from public.sanji_discovery_usage where owner=p_owner and day=d::date and companies>=r.target) then return null;end if;
 if (select count(*) from public.sanji_discovery_leads where owner=p_owner and status='new')>=8 then return null;end if;
 s:=r.search_state;
 if s->>'day'=d then
  if coalesce((s->>'leaseUntil')::timestamptz,now()-interval '1 day')>now() or coalesce((s->>'checked')::timestamptz,now()-interval '1 day')>now()-interval '15 minutes' then return null;end if;
  c:=coalesce((s->>'queries')::integer,0);if c>=64 then return null;end if;
 else c:=0;end if;
 s:=jsonb_build_object('day',d,'queries',c+2,'cursor',c,'status','searching','checked',now(),'leaseUntil',now()+interval '3 minutes');
 update public.sanji_discovery_config set search_state=s where owner=p_owner;
 return s;
end $function$
